import hashlib
import json

EXPECTED_HASH = "2f7849dbc9aa9c37551d69283e0ec4c7c626e599f00fe4e41beb55350e29d28b"

with open("records.json") as fh:
    rows = json.load(fh)

def canon(rl):
    return json.dumps(rl, sort_keys=True, separators=(",", ":")).encode()

def h(rl):
    return hashlib.sha256(canon(rl)).hexdigest()

print("current:", h(rows), len(rows))

# Candidate 1: change duplicate A-107 row to A-108, shift A-108->A-109, etc. (fix the collision by renumbering)
cand1 = [dict(r) for r in rows]
seen = set()
for r in cand1:
    if r["id"] in seen:
        # bump to the next free number
        base = int(r["id"].split("-")[1])
        newn = base
        while ("A-%d" % newn) in seen:
            newn += 1
        r["id"] = "A-%d" % newn
    seen.add(r["id"])
print("cand1 (first dup renumbered):", h(cand1))

# Candidate 2: the second A-107 should actually be A-108 and everything from A-108 on shifted +1
cand2 = [dict(r) for r in rows]
for r in cand2:
    n = int(r["id"].split("-")[1])
    if n >= 108:
        r["id"] = "A-%d" % (n + 1)
# the duplicate second A-107 becomes A-108
for i, r in enumerate(cand2):
    if r["id"] == "A-107":
        if i > 0 and cand2[i-1]["id"] == "A-107":
            r["id"] = "A-108"
print("cand2 (second A-107 -> A-108, shift rest):", h(cand2), [r["id"] for r in cand2])
